  "contradictory_card_ids": ["C31", "C32", "C42", "C35"],
  "prediction_basis_card_ids": [
    "C17", "C07", "C14", "C03", "C05", "C11", "C15", "C18", "C20",
    "C01", "C08", "C10", "C36", "C16", "C19", "C33", "C37", "C41"
  ],
  "claims": [
    {
      "claim": "The query combines the verapamil/gallopamil dimethoxyphenethyl-methylamino-propyl chain with a benzazepinone lactam; the most transferable verapamil fasted context has mean absolute F of 22% (17-29%), and verapamil SR contexts give 34-49%, supporting F >= 20%.",
      "card_ids": ["C17", "C07", "C14"]
    },
    {
      "claim": "Gallopamil, the closest acyclic analog, has absolute F of 15-23% (single-dose 15%, repeated 22.6%), so the class straddles the threshold; this weakens but does not affirmatively establish F < 20%.",
      "card_ids": ["C31", "C32", "C42", "C23"]
    },
    {
      "claim": "Related basic drugs with the same dimethoxyphenethyl motif have mean F above 20%: bevantolol 57-60%, vernakalant 58-71%, and drotaverine 58.2%.",
      "card_ids": ["C10", "C36", "C16", "C19", "C01", "C08"]
    },
    {
      "claim": "New L3 oral-exposure records for the same benzazepinone scaffold (ivabradine) and verapamil SR show measurable systemic exposure after oral dosing, but without matched IV comparators they do not directly quantify F and are therefore neutral for the threshold.",
      "card_ids": ["C64", "C89", "C60", "C87"]
    },
    {
      "claim": "The only affirmative sub-20% record in the broader analog set is rabbit ketotifen (8%), which is species-mismatched and not transferable to human oral F.",
      "card_ids": ["C35"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C64", "C89", "C60", "C87"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "L3 AUC/Cmax records lack matched IV comparators, so they cannot directly quantify F.",
    "The gallopamil context straddles the threshold (15-23%), leaving the closest acyclic analog borderline.",
    "Verapamil fasted F range (17-29%) includes values below 20%.",
    "The effect of the benzazepinone lactam on first-pass metabolism relative to the acyclic nitrile analogs is unknown.",
    "No query-specific absorption, solubility, dissolution, or formulation data are available."
  ],
  "decision_summary": "Predicted high (F >= 20%) because the most transferable verapamil fasted context has mean F of 22%, verapamil SR/cirrhosis contexts give 34-52%, and related dimethoxyphenethyl drugs (bevantolol, vernakalant, drotaverine) have mean F of 57-71%; L3 oral-exposure records for the same benzazepinone scaffold (ivabradine) and verapamil SR show measurable oral absorption but no IV comparator, while the gallopamil 15-23% and rabbit ketotifen 8% records weaken but do not overturn the high prediction."
}

